<template lang="html">
	<div
		class="omapi-subscribers-segments"
		:class="{
			'omapi-subscribers-segments__refreshing': isLoading,
			'omapi-subscribers-segments__no-data': !hasTags,
		}"
	>
		<monsterleads-search-button
			class="omapi-subscribers-segments__search"
			placeholder="Search Tags..."
			item="tags"
		/>

		<monsterleads-table-pagination :page-total="tags.length" />
		<table-base
			:headers="headers"
			:do-select-all="false"
			:is-loading="false"
			:show-footer="false"
			class="omapi-table"
		>
			<template v-if="tags">
				<monsterleads-segments-row v-for="tag in tags" :key="tag.id" :tag="tag"></monsterleads-segments-row>
				<tr class="omapi-table__footer">
					<table-cell :colspan="4">
						<core-button
							:link-style="true"
							class="omapi-table__footer-add nohover"
							@click="$modal.show('create-tag-modal')"
							>+ Add New Tag</core-button
						>
					</table-cell>
				</tr>
			</template>
		</table-base>
		<monsterleads-table-pagination :page-total="tags.length" />
		<monsterleads-modal-create-tag />
	</div>
</template>

<script lang="js">
import { mapState, mapGetters, mapActions } from 'vuex'
import { pagination } from '@/monsterleads/mixins/pagination'

export default  {
	mixins : [ pagination ],
	data () {
		return {
			headers : [
				{ name: 'Tag Name', class: 'tag-table-name' },
				{ name: 'Created On', class: 'tag-table-created' },
				{ name: 'All Time Subscribers', class: 'tag-table-stats' },
				{ name: 'Last 30 Day Subscribers', class: 'tag-table-stats' },
			],
		}
	},
	computed : {
		...mapGetters([ 'connected', 'shouldFetchUser' ]),
		...mapState('monsterleads', [ 'tags', 'count' ]),
		isLoading () {
			return this.shouldFetchUser || this.$store.getters.isLoading('lead-tags')
		},
		hasTags () {
			return 0 < this.count
		},
	},
	methods : {
		...mapActions('monsterleads', {
			fetch : 'fetchLeadsTags',
		}),
	},
};
</script>

